//! Committed containers, read through the current reader.
//!
//! The files under `tests/fixtures/archive` are sealed containers whose exact bytes are
//! pinned here by digest. A reader change that alters what any of them resolves to, or a
//! writer change that alters the bytes it seals, fails these tests instead of passing
//! against a fixture regenerated by the changed code.
use super::*;

/// The members every committed fixture container holds, in append order. Address order
/// differs from append order on purpose, so an index sorted by address is not also
/// sorted by offset.
pub(super) fn fixture_members() -> Vec<(String, Vec<u8>)> {
    vec![
        (
            "fedcba9876543210".to_owned(),
            (0..300u32).map(|i| ((i * 7 + 3) % 256) as u8).collect(),
        ),
        ("0123456789abcdef".to_owned(), (0..=255).collect()),
        ("5f3c9e0d12ab4477".to_owned(), b"history".to_vec()),
        ("00000000000000a1".to_owned(), Vec::new()),
    ]
}

/// The path of a committed fixture, built per component so it is valid on every platform.
pub(super) fn fixture_path(dir: &str, name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join("archive")
        .join(dir)
        .join(name)
}

fn sha256_hex(bytes: &[u8]) -> String {
    Sha256::digest(bytes)
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}

/// The v1 container as the v0.3.162 writer sealed it: four members, then a 132-byte
/// index (count, four entries in append order) and the trailer.
const V1_FIXTURE_SHA256: &str = "44cce40e20a69024cd538722fc03082e3692caca14ee0f8a91817ccd22b94249";

/// The same members under a v2 index, and an empty (count 0) v2 container. Both are
/// readable by v0.3.162, which predates v2, and every member resolves there.
const V2_FIXTURE_SHA256: &str = "311b931e3b030b4e6082390d61b5b79cfb6063597eec3c85cca26c1bb12bc8a0";
const V2_EMPTY_FIXTURE_SHA256: &str =
    "cd4c4682a08b4112843596dc7568291f0b961f1d265b0ea1f63487df94d7c131";

fn v2_fixture() -> PathBuf {
    fixture_path("v2", "fold-1002.ark")
}

fn v2_empty_fixture() -> PathBuf {
    fixture_path("v2-empty", "fold-1003.ark")
}

fn v1_fixture() -> PathBuf {
    fixture_path("v1", "fold-1001.ark")
}

/// Every member's header location, in append order. A reader that reads the fixture
/// differently, not just one that fails to read it, changes these.
fn expected_infos() -> Vec<MemberInfo> {
    let mut offset = 0;
    fixture_members()
        .into_iter()
        .map(|(session_addr, payload)| {
            let info = MemberInfo {
                session_addr,
                offset,
                payload_len: payload.len() as u64,
                payload_sha256: Sha256::digest(&payload).into(),
            };
            offset += MEMBER_HEADER_LEN + payload.len() as u64;
            info
        })
        .collect()
}

#[test]
fn container_magic_and_member_format_are_pinned() {
    // Every released reader recognises a sealed container by this trailer magic and a
    // member by this header magic and version. Changing any of them makes older builds
    // skip sealed containers or refuse every member, so they never change.
    assert_eq!(MAGIC.to_le_bytes(), *b"WALK");
    assert_eq!(MAGIC_MEMBER.to_le_bytes(), *b"WALM");
    assert_eq!(FORMAT_VERSION, 1);
    assert_eq!(MEMBER_HEADER_LEN, 64);
}

#[test]
fn committed_v1_fixture_bytes_are_pinned() {
    let bytes = std::fs::read(v1_fixture()).unwrap();
    assert_eq!(bytes.len(), 959);
    assert_eq!(sha256_hex(&bytes), V1_FIXTURE_SHA256);
}

#[test]
fn committed_v1_fixture_resolves_every_member_byte_for_byte() {
    let path = v1_fixture();
    let infos = expected_infos();
    let mut reader = ArchiveReader::open(&path, 1024).unwrap();
    assert_eq!(reader.state().unwrap(), ContainerState::Sealed);
    for ((_, payload), info) in fixture_members().into_iter().zip(&infos) {
        let member = reader.read_member(&info.session_addr).unwrap().unwrap();
        assert_eq!(&member.info, info);
        assert_eq!(member.payload, payload);
        let newest = read_newest_member(std::slice::from_ref(&path), &info.session_addr, 1024)
            .unwrap()
            .unwrap();
        assert_eq!(newest, member);
    }
    assert!(reader.read_member("ffffffffffffffff").unwrap().is_none());
    assert!(
        read_newest_member(std::slice::from_ref(&path), "ffffffffffffffff", 1024)
            .unwrap()
            .is_none()
    );
    assert_eq!(
        ArchiveReader::open(&path, 0).unwrap().rescan().unwrap(),
        infos
    );
}

#[test]
fn committed_v2_fixture_bytes_are_pinned() {
    let bytes = std::fs::read(v2_fixture()).unwrap();
    assert_eq!(bytes.len(), 959 + 64);
    assert_eq!(sha256_hex(&bytes), V2_FIXTURE_SHA256);
    let empty = std::fs::read(v2_empty_fixture()).unwrap();
    assert_eq!(empty.len(), 4 + 64 + 8);
    assert_eq!(sha256_hex(&empty), V2_EMPTY_FIXTURE_SHA256);
    // The layout the format describes, independently of the reader: the member region
    // is the v1 fixture's, then the index lists the members by address.
    let v1 = std::fs::read(v1_fixture()).unwrap();
    let members_end = 959 - 8 - (4 + 4 * 32);
    assert_eq!(bytes[..members_end], v1[..members_end]);
    let mut by_address = expected_infos();
    by_address.sort_by(|a, b| a.session_addr.cmp(&b.session_addr));
    assert_eq!(bytes[members_end..members_end + 4], 4u32.to_le_bytes());
    for (n, info) in by_address.iter().enumerate() {
        let at = members_end + 4 + 32 * n;
        assert_eq!(&bytes[at..at + 16], info.session_addr.as_bytes());
        assert_eq!(bytes[at + 16..at + 24], info.offset.to_le_bytes());
        assert_eq!(bytes[at + 24..at + 32], info.payload_len.to_le_bytes());
    }
    let tail = bytes.len() - 8;
    assert_eq!(&bytes[tail - 32..tail - 28], b"IDX2");
    assert!(bytes[tail - 28..tail].iter().all(|byte| *byte == 0));
    assert_eq!(bytes[tail..tail + 4], (4u32 + 4 * 32 + 64).to_le_bytes());
    assert_eq!(&bytes[tail + 4..], b"WALK");
}

#[test]
fn committed_v2_fixtures_verify_and_resolve_every_member() {
    let path = v2_fixture();
    let infos = expected_infos();
    let mut reader = ArchiveReader::open(&path, 1024).unwrap();
    for ((_, payload), info) in fixture_members().into_iter().zip(&infos) {
        let member = reader.read_member(&info.session_addr).unwrap().unwrap();
        assert_eq!(&member.info, info);
        assert_eq!(member.payload, payload);
        let newest = read_newest_member(std::slice::from_ref(&path), &info.session_addr, 1024)
            .unwrap()
            .unwrap();
        assert_eq!(newest, member);
    }
    assert!(matches!(reader.index, Some(IndexOutcome::Verified { .. })));
    assert!(reader.read_member("ffffffffffffffff").unwrap().is_none());
    assert!(
        read_newest_member(std::slice::from_ref(&path), "ffffffffffffffff", 1024)
            .unwrap()
            .is_none()
    );
    assert_eq!(
        ArchiveReader::open(&path, 0).unwrap().rescan().unwrap(),
        infos
    );

    let empty = v2_empty_fixture();
    let mut reader = ArchiveReader::open(&empty, 1024).unwrap();
    assert_eq!(reader.state().unwrap(), ContainerState::Sealed);
    for (addr, _) in fixture_members() {
        assert!(reader.read_member(&addr).unwrap().is_none());
    }
    assert!(matches!(reader.index, Some(IndexOutcome::Verified { .. })));
    assert!(ArchiveReader::open(&empty, 0)
        .unwrap()
        .rescan()
        .unwrap()
        .is_empty());
}

/// The writer local to the v2 tests, which lays bytes out from the format description,
/// reproduces both committed v2 fixtures.
#[test]
fn the_format_description_reproduces_the_committed_v2_fixtures() {
    assert_eq!(
        super::v2_tests::v2_container(1002, &fixture_members()),
        std::fs::read(v2_fixture()).unwrap()
    );
    assert_eq!(
        super::v2_tests::v2_container(1003, &[]),
        std::fs::read(v2_empty_fixture()).unwrap()
    );
}

/// The writer seals exactly the committed v2 fixtures, which v0.3.162 (a build that
/// predates index format v2) resolves member for member. A writer that changed the trailer
/// magic, the member header or its version would no longer reproduce them.
#[test]
fn writer_reproduces_the_committed_v2_fixtures() {
    let dir = broca_test_support::scratch_root()
        .join(format!("broca-archive-fixture-v2-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).unwrap();
    for (stamp, members, fixture) in [
        (1002, fixture_members(), v2_fixture()),
        (1003, Vec::new(), v2_empty_fixture()),
    ] {
        let path = dir.join(format!("fold-{stamp}.ark"));
        let mut writer = ArchiveWriter::create(&path)
            .unwrap()
            .without_feature_floor();
        for (addr, payload) in members {
            writer.append(&addr, &payload).unwrap();
        }
        writer.seal().unwrap();
        assert_eq!(
            std::fs::read(&path).unwrap(),
            std::fs::read(fixture).unwrap()
        );
    }
    std::fs::remove_dir_all(&dir).unwrap();
}
